namespace pcms.Domain.Entities;
public class SupplyItem { public Guid Id { get; set; } public string Name { get; set; } = string.Empty; public string? Description { get; set; } public string? InternalSku { get; set; } public string Category { get; set; } = string.Empty; public string UnitOfMeasure { get; set; } = string.Empty; public bool TrackInventory { get; set; } = true; public decimal MinimumQuantity { get; set; } public string ScanCode { get; set; } = string.Empty; public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } public DateTime? UpdatedAt { get; set; } }
